import type { CourseText } from "./course";

export type CourseMedia = {
  mindMap?: {
    path: string;
    title: CourseText;
    caption: CourseText;
    outline: CourseText[];
  };
  noteFigures?: Array<{
    path: string;
    sectionId: string;
    title: CourseText;
    caption: CourseText;
    alt: CourseText;
  }>;
  textbookFigures?: Array<{
    path: string;
    sectionId: string;
    figureRef: string;
    page: number | number[];
    title: CourseText;
    caption: CourseText;
    check: CourseText;
    alt: CourseText;
  }>;
  textbookAtlas: Array<{
    title: CourseText;
    relationship: CourseText;
    steps: CourseText[];
  }>;
};

const t = (en: string, zh: string): CourseText => ({ en, zh });

const textbookFigure = (
  file: string,
  sectionId: string,
  figureRef: string,
  page: number | number[],
  titleEn: string,
  titleZh: string,
  captionEn: string,
  captionZh: string,
  checkEn: string,
  checkZh: string,
) => ({
  path: `textbook/chapter-01/${file}`,
  sectionId,
  figureRef,
  page,
  title: t(titleEn, titleZh),
  caption: t(captionEn, captionZh),
  check: t(checkEn, checkZh),
  alt: t(`${figureRef}: ${titleEn}`, `${figureRef}：${titleZh}`),
});

const textbookFigureForChapter = (
  chapter: number,
  file: string,
  sectionId: string,
  figureRef: string,
  page: number | number[],
  titleEn: string,
  titleZh: string,
  captionEn: string,
  captionZh: string,
  checkEn: string,
  checkZh: string,
) => ({
  path: `textbook/chapter-${String(chapter).padStart(2, "0")}/${file}`,
  sectionId: ({
    19: { physiology: "ssc", "landing-safety": "technique", "lower-body-technique": "technique", "upper-body-technique": "technique", "trunk-technique": "technique", "program-design": "program" },
    20: { "maximum-velocity": "speed", acceleration: "speed", agility: "perception", overview: "design" },
    23: {
      "allied-health": "team",
      "injury-classification": "healing",
      "tissue-healing": "healing",
      "rehab-progression": "progression",
      "return-to-play": "progression",
      "program-design": "progression",
      "injury-risk-reduction": "progression",
      "medical-conditions": "redflags",
    },
    22: {
      foundations: "hierarchy",
      "planning-levels": "hierarchy",
      "periodization-hierarchy": "hierarchy",
      "adaptation-models": "models",
      "planning-models": "models",
      "traditional-model": "models",
      "training-phases": "models",
      "season-integration": "annual",
      "annual-plan-example": "annual",
      "annual-plan-off-season": "annual",
      "annual-plan-preseason": "annual",
      "annual-plan-in-season": "annual",
      "annual-plan-postseason": "annual",
      "peaking-maintenance": "taper",
      "active-rest": "taper",
    },
  } as Record<number, Record<string, string>>)[chapter]?.[sectionId] || sectionId,
  figureRef,
  page,
  title: t(titleEn, titleZh),
  caption: t(captionEn, captionZh),
  check: t(checkEn, checkZh),
  alt: t(`${figureRef}: ${titleEn}`, `${figureRef}：${titleZh}`),
});

const map = (path: string, en: string, zh: string, outline: CourseText[]) => ({
  path,
  title: t(en, zh),
  caption: t(
    "Personal study map supplied by the learner. Use it for retrieval after completing the lesson, and verify any conflicting wording against the fifth edition.",
    "学习者提供的个人思维导图。请先学习英文主课程，再用它主动回忆；如有冲突，以第五版英文内容为准。",
  ),
  outline,
});

